CREATE OR REPLACE VIEW "EXT"."CSA_RESUMEN_REPARTO_PAGOS_VB1_SVW" ( "PERIODSEQ", "PERIODO", "PERIODO_FORMATO", "COMPANIA", "CONCEPTO_CONTABLE", "TIPO_PAGO", "NUM_TRAMO", "PRODUCTID", "IMPORTE", "AGENCIA" ) AS (SELECT "PERIODSEQ" , "PERIODO" , "PERIODO_FORMATO" , "COMPANIA" , concepto_contable, "TIPO_PAGO" , "NUM_TRAMO" , "PRODUCTID" , "IMPORTE" , "AGENCIA" FROM EXT.OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP WHERE PERIODSEQ IN
(SELECT PERIODSEQ FROM  cs_period where startdate like'2026-%' and removedate= TO_DATE('2200-01-01','YYYY-MM-DD')));
